1	import { SPEED_MODE_OPTIONS, type SpeedMode } from './agent_profiles';
2	
3	/** Distinguish a requested speed from the tier acknowledged by the provider. */
4	export function agentSpeedLabel(settings: { speedMode?: SpeedMode; acknowledgedServiceTier?: string | null }) {
5	    const { speedMode, acknowledgedServiceTier } = settings;
6	    const requested = speedMode ? `requested speed: ${SPEED_MODE_OPTIONS.find(({ value }) => value === speedMode)?.label}` : '';
7	    const acknowledged = acknowledgedServiceTier !== undefined ? `provider tier: ${acknowledgedServiceTier ?? 'provider default'}` : '';
8	
9	    return [requested, acknowledged].filter((value) => !!value).join('; ');
10	}
